int main(void) {
    int stack_var = 12345;
    size_t num_ops = sizeof(ops) / sizeof(ops[0]);
    for (size_t i = 0; i < num_ops; i++) {
        int op = ops[i].op;
        int a = ops[i].a;
        int b = ops[i].b;
        int c = ops[i].c;
        switch (op) {
            case 1: {
                ptrs[a] = my_malloc((size_t)b);
                sizes[a] = (size_t)b;
                if (!ptrs[a]) printf("UNEXPECTED NULL malloc at %zu\n", i);
                else fill_pattern(ptrs[a], (size_t)b, c);
                break;
            }
            case 2: {
                size_t nmemb = (size_t)b;
                size_t sz = (size_t)(c >> 8);
                int seed = c & 0xFF;
                size_t tot = nmemb * sz;
                ptrs[a] = my_calloc(nmemb, sz);
                sizes[a] = tot;
                if (!ptrs[a]) {
                    printf("UNEXPECTED NULL calloc at %zu\n", i);
                } else {
                    size_t lim = tot < 64 ? tot : 64;
                    for (size_t k = 0; k < lim; k++) {
                        if (ptrs[a][k] != 0) {
                            printf("CALLOC NOT ZERO at %zu\n", i);
                            break;
                        }
                    }
                    fill_pattern(ptrs[a], tot, seed);
                }
                break;
            }
            case 3: {
                if (b == 0) {
                    void *r = my_realloc(ptrs[a], 0);
                    if (r != NULL) printf("UNEXPECTED NON-NULL realloc(0) at %zu\n", i);
                } else {
                    size_t preserve_len = (size_t)(c >> 8);
                    int new_seed = c & 0xFF;
                    int old_seed = 0;
                    if (preserve_len > 0) {
                        old_seed = (int)ptrs[a][0];
                    }
                    unsigned char *np = my_realloc(ptrs[a], (size_t)b);
                    if (!np) {
                        printf("UNEXPECTED NULL realloc at %zu\n", i);
                    } else {
                        check_pattern(np, preserve_len, old_seed, (int)i);
                        ptrs[a] = np;
                        sizes[a] = (size_t)b;
                        fill_pattern(np, (size_t)b, new_seed);
                    }
                }
                break;
            }
            case 4:
                my_free(ptrs[a]);
                break;
            case 5:
                my_set_policy(a);
                break;
            case 6:
                my_set_delay(a);
                break;
            case 7:
                ptrs[a][sizes[a] + (size_t)b] = (unsigned char)c;
                break;
            case 8:
                ptrs[a][b] = (unsigned char)c;
                break;
            case 9:
                my_free(ptrs[a]);
                break;
            case 10:
                my_free(ptrs[a] + b);
                break;
            case 11:
                my_free(&stack_var);
                break;
            case 12:
                if (my_realloc(&stack_var, (size_t)a) != NULL)
                    printf("UNEXPECTED stack realloc at %zu\n", i);
                break;
            case 13:
                check_pattern(ptrs[a], (size_t)b, c, (int)i);
                break;
            case 14:
                my_heap_dump();
                break;
            case 15:
                my_leak_report();
                break;
        }
    }
    return 0;
}
